    @ResourceGroupPreparer(name_prefix='cli_test_fileshares_identity', location=LOCATION)
    def test_fileshares_identity(self, resource_group):
        self.kwargs.update({
            'name': self.create_random_name('share', 24),
            'location': LOCATION,
            'uami': self.create_random_name('cli-uami-', 24),
        })
        uami = self.cmd('identity create -g {rg} -n {uami} -l {location}').get_output_in_json()
        self.kwargs['uami_id'] = uami['id']

        # Create with a system-assigned identity
        self._create_share(extra_args='--system-assigned')
        self.cmd(
            'fileshare identity show -g {rg} -n {name}',
            checks=[
                self.check('type', 'SystemAssigned'),
                self.exists('principalId'),
                self.exists('tenantId'),
            ]
        )

        # Add a user-assigned identity
        self.cmd(
            'fileshare identity assign -g {rg} -n {name} --user-assigned {uami_id}',
            checks=[
                self.check('type', 'SystemAssigned,UserAssigned'),
                self.exists('principalId'),
                self.check('length(userAssignedIdentities)', 1),
            ]
        )

        # Remove the system-assigned identity
        self.cmd(
            'fileshare identity remove -g {rg} -n {name} --system-assigned',
            checks=[
                self.check('type', 'UserAssigned'),
                self.check('length(userAssignedIdentities)', 1),
            ]
        )

        # Remove the user-assigned identity, leaving none
        self.cmd('fileshare identity remove -g {rg} -n {name} --user-assigned {uami_id}')
        self.cmd(
            'fileshare show -g {rg} -n {name}',
            checks=[
                self.check("identity == `null` || identity.type == 'None'", True),
            ]
        )

        self.cmd('fileshare delete -g {rg} -n {name} --yes')

