    @AllowLargeResponse()
    @ResourceGroupPreparer(name_prefix='cli_test_fileshares_cmk', location=LOCATION)
    def test_fileshares_customer_managed_key(self, resource_group):
        # Live only: the scenario needs role assignments (random names) and Key Vault data-plane calls.
        self.kwargs.update({
            'name': self.create_random_name('share', 24),
            'location': LOCATION,
            'uami': self.create_random_name('cli-uami-', 24),
            'vault': self.create_random_name('clicmk', 24),
            'key1': self.create_random_name('key1-', 16),
            'key2': self.create_random_name('key2-', 16),
            'crypto_user': KEY_VAULT_CRYPTO_USER_ROLE,
            'crypto_officer': KEY_VAULT_CRYPTO_OFFICER_ROLE,
        })

        uami = self.cmd('identity create -g {rg} -n {uami} -l {location}').get_output_in_json()
        self.kwargs.update({'uami_id': uami['id'], 'uami_principal': uami['principalId']})
        self.kwargs['user_id'] = self.cmd('ad signed-in-user show').get_output_in_json()['id']

        vault = self.cmd('keyvault create -g {rg} -n {vault} -l {location} '
                         '--enable-rbac-authorization true --retention-days 7').get_output_in_json()
        self.kwargs['vault_id'] = vault['id']
        self.cmd('role assignment create --role "{crypto_user}" --assignee-object-id {uami_principal} '
                 '--assignee-principal-type ServicePrincipal --scope {vault_id}')
        self.cmd('role assignment create --role "{crypto_officer}" --assignee-object-id {user_id} '
                 '--assignee-principal-type User --scope {vault_id}')

        key1 = self._create_key_with_rbac_retry('key1')
        key2 = self._create_key_with_rbac_retry('key2')
        self.kwargs.update({
            'cmk1': self._customer_managed_key_shorthand(key1['key']['kid'].rsplit('/', 1)[0]),
            'cmk2': self._customer_managed_key_shorthand(key2['key']['kid'].rsplit('/', 1)[0]),
        })

        # Create with a customer-managed key (unversioned key URL, so the service tracks the latest version)
        self._create_share(extra_args='--user-assigned {uami_id} --encryption "{cmk1}"')
        share = self.cmd(
            'fileshare show -g {rg} -n {name}',
            checks=[
                self.check('identity.type', 'UserAssigned'),
                self.check('properties.encryption.customerManagedKeyEncryption.keyEncryptionKeyIdentity.identityType',
                           'userAssignedIdentity'),
                self.exists('properties.encryption.lastKeyRotationTimestamp'),
                self.check('properties.encryption.autoKeyRotationError', None),
            ]
        ).get_output_in_json()
        self.assertEqual(key1['key']['kid'].lower(), share['properties']['encryption']['currentKeyEncryptionKeyUrl'].lower())
        first_rotation = share['properties']['encryption']['lastKeyRotationTimestamp']

        # Rotate to the second key with an update
        self.cmd('fileshare update -g {rg} -n {name} --encryption "{cmk2}"')
        share = self.cmd('fileshare show -g {rg} -n {name}').get_output_in_json()
        self.assertEqual(key2['key']['kid'].lower(), share['properties']['encryption']['currentKeyEncryptionKeyUrl'].lower())
        self.assertNotEqual(first_rotation, share['properties']['encryption']['lastKeyRotationTimestamp'])

        self.cmd('fileshare delete -g {rg} -n {name} --yes')
        self.cmd('keyvault delete -n {vault}')
        self.cmd('keyvault purge -n {vault} -l {location}')

    def _customer_managed_key_shorthand(self, key_url):
        return ("{customer-managed-key-encryption:{key-encryption-key-url:'%s',key-encryption-key-identity:"
                "{identity-type:userAssignedIdentity,user-assigned-identity-resource-id:'%s'}}}"
                % (key_url, self.kwargs['uami_id']))

    def _create_key_with_rbac_retry(self, key_name_key):
        # Key Vault data-plane role assignments take a short while to take effect.
        for attempt in range(12):
            try:
                return self.cmd('keyvault key create --vault-name {vault} -n {%s}' % key_name_key).get_output_in_json()
            except Exception:  # pylint: disable=broad-except
                if attempt == 11:
                    raise
                time.sleep(10)

    @unittest.skip(REDUNDANCY_CONVERSION_PENDING)
    @AllowLargeResponse()
    @ResourceGroupPreparer(name_prefix='cli_test_fileshares_conversion', location=LOCATION)
    def test_fileshares_redundancy_conversion(self, resource_group):
        self.kwargs.update({
            'name': self.create_random_name('share', 24),
            'location': LOCATION,
        })
        self._create_share()

        # Starting a conversion is a synchronous accept; the conversion itself can take days, so it is never awaited.
        self.cmd('fileshare start-redundancy-conversion -g {rg} --resource-name {name} --target-redundancy Zone')

        status = self.cmd(
            'fileshare get-redundancy-conversion-status -g {rg} --resource-name {name}',
            checks=[
                self.check('properties.targetRedundancy', 'Zone'),
            ]
        ).get_output_in_json()
        conversion_status = status['properties']['conversionStatus']
        self.assertIn(conversion_status, ['SubmittedForConversion', 'InProgress', 'Complete'])

        if conversion_status != 'Complete':
            self.cmd(
                'fileshare show -g {rg} -n {name}',
                checks=[
                    self.check('properties.migrationState.redundancyConversionInProgress', True),
                    self.check('properties.provisioningState', 'Succeeded'),
                ]
            )

            # The share stays fully usable while it converts.
            self.cmd(
                'fileshare update -g {rg} -n {name} --tags redundancy-conversion=started',
                checks=[
                    self.check('tags."redundancy-conversion"', 'started'),
                ]
            )

            # Only one conversion may run at a time.
            self.cmd('fileshare start-redundancy-conversion -g {rg} --resource-name {name} --target-redundancy Zone',
                     expect_failure=True)

        self.cmd('fileshare delete -g {rg} -n {name} --yes')

